//! The existing checked in-place DATA sorter; no source, parser or model authority.
pub fn heapsort<T,E>(rows:&mut[T],compare:&mut impl FnMut(&T,&T)->Result<std::cmp::Ordering,E>)->Result<(),E>{fn sift<T,E>(rows:&mut[T],mut root:usize,end:usize,compare:&mut impl FnMut(&T,&T)->Result<std::cmp::Ordering,E>)->Result<(),E>{loop{let Some(mut child)=root.checked_mul(2).and_then(|n|n.checked_add(1)).filter(|child|*child<end)else{return Ok(())};if child+1<end&&compare(&rows[child],&rows[child+1])?==std::cmp::Ordering::Less{child+=1}if compare(&rows[root],&rows[child])?!=std::cmp::Ordering::Less{return Ok(())}rows.swap(root,child);root=child;}}let len=rows.len();for start in(0..len/2).rev(){sift(rows,start,len,compare)?}for end in(1..len).rev(){rows.swap(0,end);sift(rows,0,end,compare)?}Ok(())}
